// Regenerates docs/adr/README.md from the ADR files.
// Usage: node adr-index.mjs [projectDir]   (defaults to the current directory)

import { readdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { parseFrontmatter } from "../core/adr-index.mjs";

const ADR_FILE = /^(\d{4})-.+\.md$/;
const HEADER = [
  "# Architecture decision records",
  "",
  "<!-- This index is generated by adr-index.mjs from docs/adr/*.md; do not edit it by hand. -->",
  "",
].join("\n");

const cell = (text) => text.replaceAll("|", String.raw`\|`);

/** Renders the README from `{ number, file, title, status, date }` entries. */
export function renderIndex(entries) {
  const rows = [...entries]
    .sort(
      (a, b) =>
        a.number.localeCompare(b.number) || a.file.localeCompare(b.file),
    )
    .map(
      (e) =>
        `| ${e.number} | [${cell(e.title)}](${e.file}) | ${e.status} | ${e.date} |`,
    );
  return `${[
    HEADER,
    "| Number | Title | Status | Date |",
    "| --- | --- | --- | --- |",
    ...rows,
  ].join("\n")}\n`;
}

/** Reads docs/adr under projectDir and returns the rendered index. */
export async function buildIndex(projectDir) {
  const adrDir = path.join(projectDir, "docs", "adr");
  const names = (await readdir(adrDir)).filter((n) => ADR_FILE.test(n));
  const entries = [];
  for (const file of names) {
    const text = await readFile(path.join(adrDir, file), "utf8");
    const meta = parseFrontmatter(text) ?? {};
    const heading = /^# (.+?)\s*$/m.exec(text.replace(/\r\n/g, "\n"));
    entries.push({
      number: ADR_FILE.exec(file)[1],
      file,
      title: heading ? heading[1] : file.replace(/\.md$/, ""),
      status: meta.status ?? "unknown",
      date: meta.date ?? "",
    });
  }
  return renderIndex(entries);
}

async function main() {
  const projectDir = path.resolve(process.argv[2] ?? process.cwd());
  let output;
  try {
    output = await buildIndex(projectDir);
  } catch (error) {
    const reason =
      error.code === "ENOENT"
        ? `no docs${path.sep}adr directory in ${projectDir}`
        : error.message;
    process.stderr.write(`adr-index: ${reason}\n`);
    process.exitCode = 1;
    return;
  }
  const target = path.join(projectDir, "docs", "adr", "README.md");
  await writeFile(target, output);
  process.stdout.write(`adr-index: wrote ${target}\n`);
}

if (
  process.argv[1] &&
  path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)
) {
  await main();
}
